
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ncapr_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ncapr", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.310851210290671e+00, -4.229360702985256e+00, -4.115299230959417e+00, -3.957560964927190e+00, -3.743180491489037e+00, -3.459030010869671e+00, -3.095744104524959e+00, -2.654623745029065e+00, -2.155969372483118e+00, -1.637751649321498e+00, -1.117599645433564e+00, -7.123452927616933e-01, -6.026842046245224e-01, -5.032578262998464e-01, -3.748025308215459e-01, -2.538664558699392e-01, -1.689005027896189e-01, -1.448435674281035e-01, -2.094112691059357e-01, -3.986737080865572e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


